import{c as a,Q as r,j as o,m as n}from"./chunks/framework.BXc4yaFE.js";const g=JSON.parse('{"title":"Live-Evo: Online Evolution of Agentic Memory from Continuous Feedback","description":"","frontmatter":{"url":"https://arxiv.org/abs/2602.02369","title":"Live-Evo: Online Evolution of Agentic Memory from Continuous Feedback","archived_date":"2026-06-24T00:00:00.000Z","arxiv_id":2602.02369,"authors":["Yaolun Zhang","Yiran Wu","Yijiong Yu","Qingyun Wu","Huazheng Wang"],"domains":["cs.AI","cs.LG"],"html":"https://arxiv.org/html/2602.02369v1","pdf_path":"pdfs/2602.02369.pdf","published_date":"2026-02-02T00:00:00.000Z"},"headers":[],"relativePath":"research/papers/2026-02-02-live-evo-online-agentic-memory-feedback-2602-02369.md","filePath":"research/papers/2026-02-02-live-evo-online-agentic-memory-feedback-2602-02369.md","lastUpdated":1785909234000}'),t={name:"research/papers/2026-02-02-live-evo-online-agentic-memory-feedback-2602-02369.md"};function i(s,e,l,c,d,h){return r(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="live-evo-online-evolution-of-agentic-memory-from-continuous-feedback" tabindex="-1">Live-Evo: Online Evolution of Agentic Memory from Continuous Feedback <a class="header-anchor" href="#live-evo-online-evolution-of-agentic-memory-from-continuous-feedback" aria-label="Permalink to &quot;Live-Evo: Online Evolution of Agentic Memory from Continuous Feedback&quot;">​</a></h1><p><strong>Authors</strong>: Yaolun Zhang, Yiran Wu, Yijiong Yu, Qingyun Wu, Huazheng Wang <strong>Published</strong>: February 2, 2026 <strong>Source</strong>: <a href="https://arxiv.org/abs/2602.02369" target="_blank" rel="noreferrer">https://arxiv.org/abs/2602.02369</a> · <a href="https://arxiv.org/html/2602.02369v1" target="_blank" rel="noreferrer">HTML</a><strong>arXiv ID</strong>: 2602.02369 <strong>Categories</strong>: cs.AI, cs.LG <strong>PDF</strong>: <a href="https://arxiv.org/abs/2602.02369" target="_blank" rel="noreferrer">research/papers/pdfs/2602.02369.pdf</a> (14 pp, full text archived)</p><hr><h2 id="abstract-quoted" tabindex="-1">Abstract (quoted) <a class="header-anchor" href="#abstract-quoted" aria-label="Permalink to &quot;Abstract (quoted)&quot;">​</a></h2><blockquote><p>Large language model (LLM) agents are increasingly equipped with memory, which are stored experience and reusable guidance that can improve task-solving performance. Recent self-evolving systems update memory based on interaction outcomes, but most existing evolution pipelines are developed for static train/test splits and only approximate online learning by folding static benchmarks, making them brittle under true distribution shift and continuous feedback. We introduce LIVE-Evo, an online self-evolving memory system that learns from a stream of incoming data over time. LIVE-Evo decouples what happened from how to use it via an Experience Bank and a Meta-Guideline Bank, compiling task-adaptive guidelines from retrieved experiences for each task. To manage memory online, LIVE-Evo maintains experience weights and updates them from feedback: experiences that consistently help are reinforced and retrieved more often, while misleading or stale experiences are down-weighted and gradually forgotten, analogous to reinforcement and decay in human memory.</p></blockquote><hr><h2 id="結構化摘要" tabindex="-1">結構化摘要 <a class="header-anchor" href="#結構化摘要" aria-label="Permalink to &quot;結構化摘要&quot;">​</a></h2><h3 id="核心貢獻" tabindex="-1">核心貢獻 <a class="header-anchor" href="#核心貢獻" aria-label="Permalink to &quot;核心貢獻&quot;">​</a></h3><p>線上自演化記憶系統，針對「靜態 train/test split 近似 online learning → distribution shift 下脆弱」的缺陷。雙 bank 解耦：</p><ol><li><strong>Experience Bank</strong>（what happened）vs <strong>Meta-Guideline Bank</strong>（how to use it）— 每任務從檢索到的 experience 編譯 task-adaptive guideline。</li><li><strong>線上權重管理</strong>：experience 帶權重，依 feedback 更新——常幫上忙者<strong>增強、更常被檢索</strong>；誤導/過時者<strong>降權、漸忘</strong>（類比人腦 reinforcement/decay）。</li></ol><h3 id="關鍵結果" tabindex="-1">關鍵結果 <a class="header-anchor" href="#關鍵結果" aria-label="Permalink to &quot;關鍵結果&quot;">​</a></h3><ul><li>Prophet Arena（10 週 horizon）：Brier score <strong>+20.8%</strong> 改善、market returns <strong>+12.9%</strong>；增益遷移至 deep-research benchmark。</li></ul><h3 id="限制" tabindex="-1">限制 <a class="header-anchor" href="#限制" aria-label="Permalink to &quot;限制&quot;">​</a></h3><ul><li>14 pp；權重更新依賴可靠 feedback 信號，feedback 稀疏時退化未深入。</li></ul><hr><h2 id="workspace-關聯-評估-非既成結論" tabindex="-1">Workspace 關聯（評估，非既成結論） <a class="header-anchor" href="#workspace-關聯-評估-非既成結論" aria-label="Permalink to &quot;Workspace 關聯（評估，非既成結論）&quot;">​</a></h2><ul><li><strong>補 <code>research-hub:deep</code> + <code>autoresearch</code>（原 <code>overnight-research</code>，v5.1 刪除） 多輪 corpus staleness</strong>：experience 加權衰退 = 過時 citation 自動降權、反覆通過 gate 的 paper 升權，強化報告查核信度（harness-synthesis §7 候選）。</li><li><strong>雙 bank ↔ 本 workspace MEMORY/LESSONS 分層</strong>：Experience Bank≈session 記錄、Meta-Guideline Bank≈LESSONS 防範規則；可作 dreaming-consolidator 的記憶分層參考。</li><li><strong>online weight 純 metadata 輕量</strong>：無需 weight update，適合 black-box；落地門檻低於 SIA 權重更新。</li><li>⚠️ 需持續 feedback 流；本 workspace 為離散 session，feedback 訊號需設計（如 SIA evaluate.py pass/fail 作信號）。</li></ul>',17)])])}const p=a(t,[["render",i]]);export{g as __pageData,p as default};
